import{_ as t,c as r,o as n,ah as o}from"./chunks/framework.PvdZnrZd.js";const u=JSON.parse('{"title":"Stripe Transfer","description":"Stripe Transfer","frontmatter":{"title":"Stripe Transfer","description":"Stripe Transfer","author":"Chirag Tyagi"},"headers":[],"relativePath":"zenith/payment/stripe-transfer.md","filePath":"zenith/payment/stripe-transfer.md"}'),a={name:"zenith/payment/stripe-transfer.md"};function l(s,e,i,p,h,d){return n(),r("div",null,[...e[0]||(e[0]=[o('<h2 id="stripe-transfer" tabindex="-1">Stripe Transfer <a class="header-anchor" href="#stripe-transfer" aria-label="Permalink to &quot;Stripe Transfer&quot;">​</a></h2><h4 id="purpose-of-this-feature" tabindex="-1"><strong>Purpose of this feature</strong>: <a class="header-anchor" href="#purpose-of-this-feature" aria-label="Permalink to &quot;**Purpose of this feature**:&quot;">​</a></h4><p>This feature lets your sellers automatically receive their total earnings once they mark the order as delivered/fulfilled/paid after the refund date.</p><p><strong>In the Stripe Transfer</strong> feature customers will pay the admin via the payment method available on the Shopify end.</p><p>The seller&#39;s earnings are transferred from the Admin Stripe account to the Seller Stripe account.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripefourteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripefourteen.webp" alt="All payment methods"></a></p><p>Now admin can choose to create a payment (transfer to the seller) only if the payment is made through a specific payment method on Shopify.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripefifteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripefifteen.webp" alt="Stripe payment method"></a></p><p>This transfer of seller earnings from  Admin to Seller Stripe account is managed by the MVM app,</p><p>then as per the settings configured by the seller on their respective stripe dashboard, the amount transferred from the Seller Stripe account to their bank account is managed by the Stripe end.</p><p><strong>Note:</strong> The stripe Transfer feature is not compatible with one country that is <strong>India.</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/02/stripe-balance-1200x476.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2023/02/stripe-balance-1200x476.png" alt="stripe-balance"></a></p><h2 id="description-for-stripe-transfers" tabindex="-1">Description for Stripe Transfers <a class="header-anchor" href="#description-for-stripe-transfers" aria-label="Permalink to &quot;Description for Stripe Transfers&quot;">​</a></h2><p>We have introduced a new option for Stripe transfers that allows admins to add a custom description to payouts.</p><p>Thus, when the admin selects Stripe Transfer, a new configuration called <strong>“Set Description in Stripe Transfer”</strong> will be displayed. After enabling this option, the admin can enter any custom description.</p><p>This description will then be automatically attached to all Stripe payouts processed through the Multivendor app and will be visible along with the transaction details on the Stripe dashboard.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripesixteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripesixteen.webp" alt="image"></a></p><h2 id="how-to-configure-the-stripe-transfer-feature" tabindex="-1">How to configure the Stripe Transfer feature? <a class="header-anchor" href="#how-to-configure-the-stripe-transfer-feature" aria-label="Permalink to &quot;How to configure the Stripe Transfer feature?&quot;">​</a></h2><p>To configure this feature, the Admin needs to follow the steps written below:</p><ul><li>Go to Multi vendor Marketplace <strong>Admin Panel</strong></li><li>Hover over the <strong>Order</strong> menu &amp; select the <strong>Checkout payment method</strong> from the drop-down menus.</li></ul><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeone.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeone.webp" alt="screenshot_1675923554142"></a></p><p>After clicking on the checkout payment method, the user will land on the checkout method page as shown in the image. The user needs to click on the add button.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripetwo.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripetwo.webp" alt="Stripe Connect"></a></p><p>Once the user clicks on the add button the stripe configuration page will open and the user needs to select the <strong>Transfer</strong> for the field <strong>&quot;use stripe for</strong>&quot;.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeseventeen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeseventeen.webp" alt="screenshot_1675923802059"></a></p><p>After fulfilling all the relevant details, the payout configuration is there <strong>AUTOPAY TO SELLER</strong>.</p><p>Once you enable this configuration, you will get the three options to select</p><h3 id="fulfill" tabindex="-1"><strong>Fulfil</strong>l: <a class="header-anchor" href="#fulfill" aria-label="Permalink to &quot;**Fulfil**l:&quot;">​</a></h3><p>If you select the fulfill option then once the seller marks the order as fulfilled then seller earnings will be transferred to the seller account.</p><h3 id="delivery" tabindex="-1"><strong>Delivery</strong>: <a class="header-anchor" href="#delivery" aria-label="Permalink to &quot;**Delivery**:&quot;">​</a></h3><p>In the case of delivery, the seller’s earnings will be transferred to the seller’s account once the order is marked as delivered.</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeeighteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeeighteen.webp" alt="Stripe Connect"></a></p><h2 id="pay-after-the-return-date" tabindex="-1"><strong>Pay after the return date:</strong> <a class="header-anchor" href="#pay-after-the-return-date" aria-label="Permalink to &quot;**Pay after the return date:**&quot;">​</a></h2><p>To enable this, the admin first needs to enable the <strong>ENABLE CASHABLE AMOUNT FOR SELLER</strong> configuration which allows you to set particular days after which you want your Sellers to receive the payment.</p><p>These days are basically the days in which your customers can refund the purchased items.</p><p>Configure the following feature by navigating through: <strong>Multivendor Marketplace Admin Panel &gt; Payment &gt; Seller Payment Configuration</strong>.</p><p>Refer to the images below:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripefive.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripefive.webp" alt="admin"></a></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripesix.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripesix.webp" alt="payment"></a></p><p>Here, the Admin needs to enter the days after which the payment will be done to his sellers for the order (order refund days),</p><p>and select whether you want to calculate the provided span of time from the delivery date, order fulfillment date, or order creation date.</p><p>Example: If you have selected the delivery date &amp; mentioned refund days (pay after days) as 30 then after 30 days of the delivery date, the Sellers will receive the payment.</p><p><strong>NOTE</strong>: Refund days should be greater than -1 otherwise it will not work.</p><p>Lastly, enable the ‘<strong>Allow seller to enter refund days</strong>‘ if you want your sellers to add their individual refund days.</p><p>Once enabled, the sellers will be able to set the refund days by visiting <strong>Marketplace Seller Panel &gt; Configuration &gt; General Configuration &gt; Enter the day &amp; save:</strong></p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/12/spp6-1-1200x542.png" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2022/12/spp6-1-1200x542.png" alt="Stripe Connect"></a></p><p><strong>Note:</strong> The sellers who have not entered any refund days will by default have the refund days set by the admin.<br> If entered then the refund days should be greater than -1 otherwise it will not work.</p><p>Only after enabling this option, the Admin will have the ‘Pay after refund date’ option in stripe Transfer Configuration:</p><p><a href="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeeighteen.webp" target="_blank" rel="noreferrer"><img src="https://cdnblog.webkul.com/blog/wp-content/uploads/2026/03/stripeeighteen.webp" alt="Stripe Connect"></a></p><p>Also, the Admin won’t be able to choose the ‘pay after’ as delivery or fulfillment because now it will work as configured in the ‘Cashable Amount for Seller’ option.</p>',50)])])}const f=t(a,[["render",l]]);export{u as __pageData,f as default};
